INSERT INTO public.contacts(id,business_id,phone_number,source_channel) VALUES ('20000000-0000-4000-a070-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101','voice');
INSERT INTO public.conversations(id,business_id,contact_id,channel) VALUES ('30000000-0000-4000-a070-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','20000000-0000-4000-a070-000000000001','voice');
INSERT INTO public.voice_sessions(id,business_id,conversation_id,call_control_id,call_session_id,caller_phone,called_phone,response_mode,status,reserved_seconds) VALUES ('40000000-0000-4000-a070-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','30000000-0000-4000-a070-000000000001','control','session','+15555550101','+15742638634','voice','starting',600);
INSERT INTO public.voice_stream_credentials(session_id,token_hash,expires_at) VALUES ('40000000-0000-4000-a070-000000000001',repeat('a',64),now()+interval '1 minute');
SELECT is((public.consume_voice_stream(repeat('a',64))).id,NULL::uuid,'cannot consume before notice is complete');
UPDATE public.voice_sessions SET notice_completed_at=now();
SELECT is((public.consume_voice_stream(repeat('a',64))).id,'40000000-0000-4000-a070-000000000001'::uuid,'stream is bound to the stored session');
SELECT is((public.consume_voice_stream(repeat('a',64))).id,NULL::uuid,'stream credential is single-use');
SELECT ok(public.activate_voice_session('40000000-0000-4000-a070-000000000001','live-1'),'activate only an eligible starting call');
SELECT ok(NOT public.activate_voice_session('40000000-0000-4000-a070-000000000001','live-2'),'cannot attach a second paid session');
SELECT public.record_voice_fragment('40000000-0000-4000-a070-000000000001','fragment','customer','Hours?',0,1000);
SELECT public.record_voice_fragment('40000000-0000-4000-a070-000000000001','fragment','customer','Hours?',0,1000);
SELECT is((SELECT count(*)::integer FROM public.messages WHERE channel='voice'),1,'retries do not duplicate transcript messages');
SELECT public.update_voice_usage('40000000-0000-4000-a070-000000000001',12,false);
SELECT public.update_voice_usage('40000000-0000-4000-a070-000000000001',8,false);
SELECT is((SELECT used_seconds FROM public.voice_sessions LIMIT 1),12::numeric,'cumulative snapshots never add or decrease usage');
SELECT public.finalize_voice_session('40000000-0000-4000-a070-000000000001','caller_hangup',NULL,false,false);
SELECT is((SELECT reserved_seconds FROM public.voice_sessions LIMIT 1),600,'unknown final usage retains its reservation');
SELECT public.update_voice_usage('40000000-0000-4000-a070-000000000001',15,true);
SELECT is((SELECT reserved_seconds FROM public.voice_sessions LIMIT 1),0,'late confirmed final usage releases unused minutes');
SELECT public.update_voice_usage('40000000-0000-4000-a070-000000000001',10,false);
SELECT is((SELECT status FROM public.voice_provider_usage WHERE provider='openai'),'confirmed','late partial events cannot unconfirm final usage');
SELECT is((SELECT seconds FROM public.voice_provider_usage WHERE provider='openai'),15::numeric,'late events cannot undercount final usage');
SELECT is((SELECT status FROM public.conversations LIMIT 1),'closed','finalization closes transcript conversation');
SELECT * FROM finish();
ROLLBACK;
